{"witnessCode": "import test from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('normalizeUrl preserves pathname with adjacent protocol-like patterns', async (t) => {
  const input = 'http://example.com/a://b://';
  const actual = normalizeUrl(input);
  assert.strictEqual(actual, input);
});"}
